from itertools import product
import json
from hashlib import sha256

LOWER=(2,2,0,0,0,0)
UPPER=(5,5,5,5,5,5)
DEGREES=list(range(4,36))
HDEGREES=[1,2,3,4,5]
REFERENCE='a3ad933b835c991bc8edccec918dce17c0e4594e4d1d4281e32946dd7e508ece'

def size(p): return sum(p)
def trim(p):
    p=tuple(p)
    while p and p[-1]==0: p=p[:-1]
    return p
def contains(a,b): # a contains b
    return all(x>=y for x,y in zip(a,b))
def partitions_between(d):
    ans=[]
    def rec(i,prev,cur,left):
        if i==6:
            if left==0:
                q=tuple(cur)
                if contains(q,LOWER): ans.append(q)
            return
        lo=LOWER[i]
        hi=min(prev,UPPER[i],left)
        for x in range(hi,lo-1,-1): rec(i+1,x,cur+[x],left-x)
    rec(0,UPPER[0],[],d)
    return ans
def horizontal(mu,lam,t):
    # mu/lam horizontal t-strip iff interlacing mu_i >= lam_i >= mu_{i+1}
    if size(mu)-size(lam)!=t or not contains(mu,lam): return False
    return all(lam[i] >= mu[i+1] for i in range(5))

out={'schema':'partition-pieri-labelled-v1','input':{'lower':list(LOWER),'upper':list(UPPER),'degrees':DEGREES,'hDegrees':HDEGREES},'ordering':'lexicographically decreasing padded 6-tuples','reference':REFERENCE,'degrees':[]}
for d in DEGREES:
    cols=partitions_between(d)
    rows=[]
    for t in HDEGREES:
        for lam in partitions_between(d-t):
            rows.append({'label':{'hDegree':t,'partition':list(lam)},'entries':[int(horizontal(mu,lam,t)) for mu in cols]})
    out['degrees'].append({'degree':d,'columns':[list(x) for x in cols],'rows':rows,'matrixShape':[len(rows),len(cols)]})
# Exact requested empty-column dimension check.
expected={31:12,32:7,33:4,34:2,35:1}
actual={x['degree']:x['matrixShape'] for x in out['degrees'] if x['degree']>=31}
out['zeroColumnCheck']={'expected':{str(k):[v,0] for k,v in expected.items()},'actual':{str(k):v for k,v in actual.items()},'pass':all(actual[d]==[expected[d],0] for d in expected)}
# The reference artifact is not present as a payload/schema in this execution environment.
out['referenceComparison']={'degrees':list(range(4,31)),'status':'NOT_PERFORMED','reason':'reference supplied only as a bare digest; no canonical payload or schema was supplied to this task-owned execution'}
payload=json.dumps(out,sort_keys=True,separators=(',',':'))
print(payload)
print('PAYLOAD_SHA256='+sha256(payload.encode()).hexdigest())
print('ZERO_COLUMN_CHECK='+str(out['zeroColumnCheck']['pass']))
print('REFERENCE_COMPARISON='+out['referenceComparison']['status'])
